# BU KODU REFACTOR EDECEKSIN!
# Anti-pattern'larla dolu, bakımı zor, test edilemez kod.

class OrderSystem:
    """God Class - her seyi yapiyor!"""

    def __init__(self):
        self.orders = []
        self.total_revenue = 0

    def process_order(self, order):
        # === PRICING - if/else cehennemi ===
        if order['customer_type'] == 'regular':
            total = order['price'] * order['quantity']
        elif order['customer_type'] == 'premium':
            total = order['price'] * order['quantity'] * 0.9
        elif order['customer_type'] == 'vip':
            total = order['price'] * order['quantity'] * 0.8
        elif order['customer_type'] == 'wholesale':
            if order['quantity'] >= 100:
                total = order['price'] * order['quantity'] * 0.6
            elif order['quantity'] >= 50:
                total = order['price'] * order['quantity'] * 0.7
            else:
                total = order['price'] * order['quantity'] * 0.75
        elif order['customer_type'] == 'employee':
            total = order['price'] * order['quantity'] * 0.5
        else:
            total = order['price'] * order['quantity']

        # === TAX CALCULATION - hardcoded ===
        if order.get('country') == 'TR':
            tax = total * 0.20  # KDV %20
        elif order.get('country') == 'US':
            tax = total * 0.08
        elif order.get('country') == 'DE':
            tax = total * 0.19
        elif order.get('country') == 'UK':
            tax = total * 0.20
        else:
            tax = total * 0.15  # Default tax

        total_with_tax = total + tax

        # === NOTIFICATION - if/else cehennemi ===
        if order.get('notify_via') == 'email':
            print(f'EMAIL: Siparis onaylandi. Toplam: {total_with_tax:.2f} TL')
            # Gercekte email gonderme kodu burada olurdu
        elif order.get('notify_via') == 'sms':
            print(f'SMS: Siparis {total_with_tax:.2f} TL')
        elif order.get('notify_via') == 'push':
            print(f'PUSH: Yeni siparis! {total_with_tax:.2f} TL')
        elif order.get('notify_via') == 'slack':
            print(f'SLACK: #orders kanalina mesaj: {total_with_tax:.2f} TL')
        elif order.get('notify_via') == 'whatsapp':
            print(f'WHATSAPP: Siparisiniz hazirlaniyor. {total_with_tax:.2f} TL')

        # === LOGGING - hardcoded ===
        print(f'LOG: Order processed - customer={order["customer_type"]}, total={total_with_tax:.2f}')

        # === ANALYTICS - hardcoded ===
        print(f'ANALYTICS: revenue={total_with_tax:.2f}, customer_type={order["customer_type"]}')

        # === INVENTORY - hardcoded ===
        print(f'INVENTORY: Stok guncelleniyor, {order["quantity"]} adet cikarildi')

        # === STORE ===
        order_record = {
            'customer_type': order['customer_type'],
            'subtotal': total,
            'tax': tax,
            'total': total_with_tax,
            'quantity': order['quantity'],
            'status': 'completed'
        }
        self.orders.append(order_record)
        self.total_revenue += total_with_tax

        return order_record

    def get_report(self):
        print(f'Toplam siparis: {len(self.orders)}')
        print(f'Toplam gelir: {self.total_revenue:.2f} TL')
        for i, order in enumerate(self.orders):
            print(f'  #{i+1}: {order["customer_type"]} - {order["total"]:.2f} TL')


